CREATE TABLE shaz_meal_days(user_id text NOT NULL REFERENCES shaz_user(id) ON DELETE CASCADE,date date NOT NULL,data jsonb NOT NULL,version integer NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,date));
CREATE TABLE shaz_cardio(id text PRIMARY KEY,user_id text NOT NULL REFERENCES shaz_user(id) ON DELETE CASCADE,day integer NOT NULL CHECK(day BETWEEN 1 AND 100),scheduled_date date NOT NULL,plan jsonb NOT NULL,status text NOT NULL DEFAULT 'planned' CHECK(status IN ('planned','completed','skipped','removed')),log jsonb NOT NULL DEFAULT '{}',updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,day));
CREATE TABLE shaz_workout_drafts(user_id text NOT NULL REFERENCES shaz_user(id) ON DELETE CASCADE,day_id text NOT NULL REFERENCES shaz_days(id) ON DELETE CASCADE,data jsonb NOT NULL,revision integer NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,day_id));
